                values[group].append(nums)
    for direction,rows in values.items():
        incorrect=[sum(r[i]<50 if direction=='dis' else r[i]>50 for r in rows) for i in range(7)]
        ties=[sum(r[i]==50 for r in rows) for i in range(7)]
        print(model,direction,'categories',len(rows),'wrong-direction counts',dict(zip(names,incorrect)),'ties',dict(zip(names,ties)))
